+
+function findClosingBracket(text: string, start: number): number {
+  let depth = 0;
+  for (let i = start; i < text.length; i++) {
+    if (text[i] === '\\\') {
+      i++;
+    } else if (text[i] === '[') {
+      depth++;
+    } else if (text[i] === ']' && --depth === 0) {
+      return i;
+    }
+  }
+  return -1;
+}
+
+function findClosingParenthesis(text: string, start: number): number {
+  let depth = 0;
+  for (let i = start; i < text.length; i++) {
+    if (text[i] === '\\\') {
+      i++;
+    } else if (text[i] === '(') {
+      depth++;
+    } else if (text[i] === ')' && --depth === 0) {
+      return i;
+    }
+  }
+  return -1;
+}
+
+function parseDestination(rawDestination: string): string | null {
+  const destination = rawDestination.trim();
+  if (destination.startsWith('<')) {
+    const close = findUnescapedCharacter(destination, '>', 1);
+    if (close === -1 || destination.substring(close + 1).trim() !== '') return null;
+    return unescapeMarkdown(destination.substring(1, close));
+  }
+  // Whitespace in a bare destination either makes it invalid or starts a title.
+  if (hasUnescapedWhitespace(destination)) return null;
+  return unescapeMarkdown(destination);
+}
+
+function findUnescapedCharacter(text: string, character: string, start: number): number {
+  for (let i = start; i < text.length; i++) {
+    if (text[i] === '\\\') i++;
+    else if (text[i] === character) return i;
